from typing import List

class Solution:
    def minOperations(self, queries: List[List[int]]) -> int:
        def g(N):
            if N < 1:
                return 0
            total = 0
            k = 1
            low = 1
            while low <= N:
                high = min(N, 4 * low - 1)
                total += k * (high - low + 1)
                low *= 4
                k += 1
            return total

        ans = 0
        for l, r in queries:
            s = g(r) - g(l - 1)
            ans += (s + 1) // 2
        return ans
